// +define+STALLS adds pseudo-random bus back-pressure on every slave.
//============================================================================
`timescale 1ns/1ps

`ifdef USE_AXI
  `define SYSIF_STR "AXI4"
`elsif USE_AHB
  `define SYSIF_STR "AHB"
`else
  `define SYSIF_STR "AVALON"
`endif

// Buses that have a real SYS error-response channel (AXI4 RRESP/BRESP, AHB
// HRESP). Avalon-MM has none, so ERR_SYS_BUS is legitimately N/A there.
`ifdef USE_AXI
  `define SYS_HAS_ERR
`elsif USE_AHB
  `define SYS_HAS_ERR
`endif

`ifdef STALLS
  `define ST 1
`else
  `define ST 0
`endif

module tb_pcie_dma;
  import dma_pkg::*;

  localparam int DW  = DATA_W;
  localparam int HAW = HADDR_W;
  localparam int SAW = SADDR_W;

  // HOST fault-injection word: any host read of this address returns a non-OK
  // PCIe completion (response=SLVERR), exercising the ERR_HOST_BUS path (test G/H).
  localparam logic [63:0] HOST_ERR_ADDR = 64'h0000_4000;
  localparam int          HOST_ERR_WORD = HOST_ERR_ADDR >> $clog2(DW/8);

  // ---- clock / reset ----
  logic clk = 0, rst_n = 0;
  always #5 clk = ~clk;            // 100 MHz

  // ---- CSR slave bus ----
  logic [CSR_ADDR_W-1:0] csr_address = '0;
  logic                  csr_read = 0, csr_write = 0;
  logic [CSR_DATA_W-1:0] csr_writedata = '0;
  logic irq, sys_bus_error, host_bus_error;

  // =================================================================
  // DUT
  // =================================================================
  // issue #14: +define+RESET_SYNC_EN drives the core/adapter through the optional
  // 2-FF reset synchronizer (RESET_SYNC=1). RST_SYNC=0 is bit-identical to the
  // historical direct-rst_n default.
`ifdef RESET_SYNC_EN
  localparam int RST_SYNC = 1;
`else
  localparam int RST_SYNC = 0;
`endif
  pcie_dma_top #(.SYS_IF(`SYSIF_STR), .RESET_SYNC(RST_SYNC)) dut (
    .clk, .rst_n,
    .csr_address, .csr_read, .csr_write, .csr_writedata,
  // Stimulus
  // =================================================================
  logic [31:0] st, ver, scr, ec, gi;
  int i, hr0;
  int rng_seed;

  initial begin
`ifdef DUMP
    $dumpfile("tb_pcie_dma.vcd");
    $dumpvars(0, tb_pcie_dma);
`endif
    $display("=== tb_pcie_dma : SYS_IF=%s STALLS=%0d ===", `SYSIF_STR, `ST);

    // deterministic RNG seed for the constrained-random tier (override with +SEED=<n>)
    if (!$value$plusargs("SEED=%d", rng_seed)) rng_seed = 32'd1;
    $display("=== tb seed = %0d ===", rng_seed);
    void'($urandom(rng_seed));   // note: Icarus updates the seed arg in place

    // hold reset
    repeat (5) @(posedge clk);
    rst_n = 1;
    gen_and_run_ring(1, 1);   // early C_LAST -> partial REG_DESC_INDEX
    gen_and_run_ring(2, 2);   // final C_LAST
    cov_report;

    // ---- report ----
    if (sys_bus_error)  begin $display("  sys_bus_error asserted");  errors++; end
    if (host_bus_error) begin $display("  host_bus_error asserted"); errors++; end
    if (errors == 0) $display("=== PASS : all checks ok ===");
    else             $display("=== FAIL : %0d error(s) ===", errors);
    $finish;
  end

  // watchdog
  initial begin
    #5_000_000;
    $display("=== FATAL: global timeout ===");
    $finish;
  end

endmodule

