122:    min3 = m;
129:    r_space     = dma_pkg::LEN_W'(DEPTH) - dma_pkg::LEN_W'(fifo_level);
130:    r_cand      = min3(dma_pkg::LEN_W'(dma_pkg::MAX_BURST_BEATS), r_rem, beats_to_boundary(r_addr));
139:    w_avail       = dma_pkg::LEN_W'(fifo_level);
